head.script:
//
  (function() {
    try {
      var t = localStorage.getItem('wkquiz_theme');
      if (t === 'dark' || (!t && window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches)) {
        document.documentElement.setAttribute('data-theme', 'dark');
        if (document.body) document.body.setAttribute('data-theme', 'dark');
      } else {
        document.documentElement.setAttribute('data-theme', 'light');
        if (document.body) document.body.setAttribute('data-theme', 'light');
      }
    } catch (e) {}
  })();
//

head.b:skin:
/**
 * ==============================================================================
 * WKQUIZ MASTER STYLESHEET
 * Mobile-First, Ultra-Lightweight, Modern CSS Design System
 * ==============================================================================
 */

:root {
  /* Core Color Palette (Light Mode Default) */
  --primary: #4f46e5;
  --primary-hover: #4338ca;
  --primary-light: #e0e7ff;
  --secondary: #06b6d4;
  --secondary-hover: #0891b2;

  --background: #f8fafc;
  --surface: #ffffff;
  --surface-2: #f1f5f9;
  --surface-3: #e2e8f0;

  --text: #0f172a;
  --text-muted: #64748b;
  --border: #e2e8f0;
  --border-focus: #6366f1;

  --success: #10b981;
  --success-light: #d1fae5;
  --success-text: #065f46;

  --danger: #ef4444;
  --danger-light: #fee2e2;
  --danger-text: #991b1b;

  --warning: #f59e0b;
  --warning-light: #fef3c7;
  --warning-text: #92400e;

  /* Typography & Layout */
  --font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Oxygen, Ubuntu, Cantarell, "Helvetica Neue", sans-serif;
  --heading-font: inherit;
  --body-font: inherit;
  --container-width: 1200px;
  --content-width: 800px;
  --radius-sm: 6px;
  --radius: 12px;
  --radius-lg: 18px;
  --radius-full: 9999px;

  /* Shadows & Transitions */
  --shadow-sm: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
  --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
  --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.1), 0 4px 6px -2px rgba(0, 0, 0, 0.05);
  --transition: all 0.2s cubic-bezier(0.4, 0, 0.2, 1);
}

/* Dark Mode Theme Overrides */
[data-theme="dark"] {
  --primary: #6366f1;
  --primary-hover: #818cf8;
  --primary-light: rgba(99, 102, 241, 0.15);
  --secondary: #22d3ee;
  --secondary-hover: #06b6d4;

  --background: #0b0f19;
  --surface: #131b2e;
  --surface-2: #1e293b;
  --surface-3: #334155;

  --text: #f8fafc;
  --text-muted: #94a3b8;
  --border: #1e293b;
  --border-focus: #818cf8;

  --success: #34d399;
  --success-light: rgba(16, 185, 129, 0.2);
  --success-text: #a7f3d0;

  --danger: #f87171;
  --danger-light: rgba(239, 68, 68, 0.2);
  --danger-text: #fecaca;

  --warning: #fbbf24;
  --warning-light: rgba(245, 158, 11, 0.2);
  --warning-text: #fde68a;

  --shadow-sm: 0 1px 2px 0 rgba(0, 0, 0, 0.4);
  --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.5);
  --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.6);
}

/* Base Reset & Box Sizing */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  font-family: var(--font-family);
  font-size: 16px;
  line-height: 1.5;
  color: var(--text);
  background-color: var(--background);
  -webkit-text-size-adjust: 100%;
  scroll-behavior: smooth;
}

body {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  background-color: var(--background);
  color: var(--text);
  overflow-x: hidden;
  transition: background-color 0.3s ease, color 0.3s ease;
}

a {
  color: var(--primary);
  text-decoration: none;
  transition: var(--transition);
}

a:hover {
  text-decoration: underline;
}

img, svg {
  display: block;
  max-width: 100%;
  height: auto;
}

button, input, select, textarea {
  font: inherit;
  color: inherit;
}

button {
  cursor: pointer;
  border: none;
  background: none;
}

:focus-visible {
  outline: 2px solid var(--border-focus);
  outline-offset: 2px;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border-width: 0;
}

/* ==============================================================================
   LAYOUT CONTAINERS & GRIDS
   ============================================================================== */
.wk-container {
  width: 100%;
  max-width: var(--container-width);
  margin-left: auto;
  margin-right: auto;
  padding-left: 1rem;
  padding-right: 1rem;
}

.wk-layout {
  display: flex;
  flex-direction: column;
  gap: 2rem;
  padding: 1.5rem 0 3rem;
}

@media (min-width: 992px) {
  .wk-layout {
    display: grid;
    grid-template-columns: 1fr 340px;
    align-items: start;
  }
}

.wk-main-content {
  min-width: 0;
}

.wk-sidebar {
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}

/* ==============================================================================
   HEADER & NAVIGATION
   ============================================================================== */
.wk-header {
  position: sticky;
  top: 0;
  z-index: 100;
  background-color: var(--surface);
  border-bottom: 1px solid var(--border);
  box-shadow: var(--shadow-sm);
  transition: var(--transition);
}

.wk-header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 64px;
  gap: 1rem;
}

.wk-brand {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  font-size: 1.4rem;
  font-weight: 800;
  color: var(--text);
  text-decoration: none;
  letter-spacing: -0.02em;
}

.wk-brand:hover {
  text-decoration: none;
}

.wk-brand-badge {
  background: linear-gradient(135deg, var(--primary), var(--secondary));
  color: #ffffff;
  padding: 0.2rem 0.6rem;
  border-radius: var(--radius-sm);
  font-size: 0.9rem;
  font-weight: 800;
}

.wk-nav-desktop {
  display: none;
  align-items: center;
  gap: 1.25rem;
}

@media (min-width: 768px) {
  .wk-nav-desktop {
    display: flex;
  }
}

.wk-nav-link {
  font-size: 0.95rem;
  font-weight: 600;
  color: var(--text-muted);
  padding: 0.5rem 0.25rem;
  text-decoration: none;
  position: relative;
}

.wk-nav-link:hover, .wk-nav-link.active {
  color: var(--primary);
  text-decoration: none;
}

.wk-nav-link.active::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  height: 2px;
  background-color: var(--primary);
  border-radius: 2px;
}

.wk-header-actions {
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.wk-btn-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 40px;
  height: 40px;
  border-radius: var(--radius-full);
  background-color: var(--surface-2);
  color: var(--text);
  transition: var(--transition);
}

.wk-btn-icon:hover {
  background-color: var(--surface-3);
  color: var(--primary);
}

.wk-mobile-menu-btn {
  display: flex;
}

@media (min-width: 768px) {
  .wk-mobile-menu-btn {
    display: none;
  }
}

/* Mobile Nav Drawer */
.wk-mobile-drawer {
  display: none;
  position: fixed;
  top: 64px;
  left: 0;
  right: 0;
  bottom: 0;
  background-color: var(--surface);
  z-index: 99;
  padding: 1.5rem;
  border-top: 1px solid var(--border);
  flex-direction: column;
  gap: 1rem;
  overflow-y: auto;
}

.wk-mobile-drawer.open {
  display: flex;
}

.wk-mobile-nav-link {
  display: block;
  font-size: 1.1rem;
  font-weight: 600;
  padding: 0.75rem 1rem;
  border-radius: var(--radius);
  color: var(--text);
  background-color: var(--surface-2);
  text-decoration: none;
}

.wk-mobile-nav-link:hover {
  background-color: var(--primary-light);
  color: var(--primary);
  text-decoration: none;
}

/* ==============================================================================
   BUTTONS & BADGES
   ============================================================================== */
.wk-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  padding: 0.75rem 1.25rem;
  min-height: 48px;
  font-size: 1rem;
  font-weight: 600;
  border-radius: var(--radius);
  transition: var(--transition);
  text-decoration: none;
  touch-action: manipulation;
}

.wk-btn-primary {
  background-color: var(--primary);
  color: #ffffff;
}

.wk-btn-primary:hover {
  background-color: var(--primary-hover);
  text-decoration: none;
  color: #ffffff;
  transform: translateY(-1px);
}

.wk-btn-secondary {
  background-color: var(--surface-2);
  color: var(--text);
  border: 1px solid var(--border);
}

.wk-btn-secondary:hover {
  background-color: var(--surface-3);
  text-decoration: none;
  color: var(--text);
}

.wk-btn-success {
  background-color: var(--success);
  color: #ffffff;
}

.wk-btn-block {
  width: 100%;
}

.wk-badge {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  padding: 0.25rem 0.6rem;
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  border-radius: var(--radius-full);
}

.wk-badge-primary { background-color: var(--primary-light); color: var(--primary); }
.wk-badge-success { background-color: var(--success-light); color: var(--success-text); }
.wk-badge-warning { background-color: var(--warning-light); color: var(--warning-text); }
.wk-badge-danger { background-color: var(--danger-light); color: var(--danger-text); }

/* ==============================================================================
   HERO SECTION
   ============================================================================== */
.wk-hero {
  background: linear-gradient(135deg, rgba(79, 70, 229, 0.08) 0%, rgba(6, 182, 212, 0.08) 100%);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 2.5rem 1.5rem;
  text-align: center;
  margin-bottom: 2rem;
}

.wk-hero-title {
  font-size: 2rem;
  font-weight: 800;
  line-height: 1.2;
  margin-bottom: 0.75rem;
  letter-spacing: -0.02em;
}

@media (min-width: 768px) {
  .wk-hero-title {
    font-size: 2.75rem;
  }
}

.wk-hero-subtitle {
  font-size: 1.1rem;
  color: var(--text-muted);
  max-width: 600px;
  margin: 0 auto 1.5rem;
}

.wk-hero-actions {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 0.75rem;
}

/* ==============================================================================
   QUIZ ENGINE INTERFACE & CARDS
   ============================================================================== */
.wk-quiz-card {
  background-color: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 1.5rem;
  box-shadow: var(--shadow-md);
  margin-bottom: 2rem;
  transition: var(--transition);
}

@media (min-width: 600px) {
  .wk-quiz-card {
    padding: 2rem;
  }
}

.wk-quiz-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 1rem;
  flex-wrap: wrap;
  gap: 0.5rem;
}

.wk-quiz-meta {
  display: flex;
  align-items: center;
  gap: 0.75rem;
}

.wk-quiz-timer {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  font-weight: 700;
  font-size: 0.9rem;
  color: var(--warning-text);
  background-color: var(--warning-light);
  padding: 0.25rem 0.6rem;
  border-radius: var(--radius-full);
}

.wk-quiz-timer.urgent {
  color: var(--danger-text);
  background-color: var(--danger-light);
  animation: pulse 1s infinite;
}

@keyframes pulse {
  0%, 100% { transform: scale(1); }
  50% { transform: scale(1.05); }
}

.wk-progress-bar-wrap {
  width: 100%;
  height: 8px;
  background-color: var(--surface-2);
  border-radius: var(--radius-full);
  overflow: hidden;
  margin-bottom: 1.5rem;
}

.wk-progress-bar-fill {
  height: 100%;
  background: linear-gradient(90deg, var(--primary), var(--secondary));
  transition: width 0.3s ease;
}

.wk-question-text {
  font-size: 1.25rem;
  font-weight: 700;
  line-height: 1.4;
  margin-bottom: 1.5rem;
  color: var(--text);
}

@media (min-width: 600px) {
  .wk-question-text {
    font-size: 1.4rem;
  }
}

/* Question Option Buttons */
.wk-options-list {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
  margin-bottom: 1.5rem;
}

.wk-option-btn {
  display: flex;
  align-items: center;
  gap: 1rem;
  width: 100%;
  min-height: 54px;
  padding: 0.85rem 1.15rem;
  text-align: left;
  background-color: var(--surface-2);
  border: 2px solid var(--border);
  border-radius: var(--radius);
  color: var(--text);
  font-size: 1rem;
  font-weight: 500;
  line-height: 1.4;
  transition: var(--transition);
  user-select: none;
}

.wk-option-btn:hover:not(:disabled) {
  border-color: var(--primary);
  background-color: var(--primary-light);
  color: var(--primary);
}

.wk-option-letter {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 32px;
  height: 32px;
  flex-shrink: 0;
  border-radius: var(--radius-sm);
  background-color: var(--surface-3);
  font-weight: 700;
  font-size: 0.9rem;
  color: var(--text);
}

.wk-option-btn:hover:not(:disabled) .wk-option-letter {
  background-color: var(--primary);
  color: #ffffff;
}

/* Correct & Incorrect States */
.wk-option-btn.correct {
  border-color: var(--success) !important;
  background-color: var(--success-light) !important;
  color: var(--success-text) !important;
  font-weight: 600;
}

.wk-option-btn.correct .wk-option-letter {
  background-color: var(--success) !important;
  color: #ffffff !important;
}

.wk-option-btn.incorrect {
  border-color: var(--danger) !important;
  background-color: var(--danger-light) !important;
  color: var(--danger-text) !important;
}

.wk-option-btn.incorrect .wk-option-letter {
  background-color: var(--danger) !important;
  color: #ffffff !important;
}

/* Explanation Box */
.wk-explanation-box {
  display: none;
  background-color: var(--surface-2);
  border-left: 4px solid var(--primary);
  border-radius: 0 var(--radius) var(--radius) 0;
  padding: 1.25rem;
  margin-bottom: 1.5rem;
  animation: fadeIn 0.3s ease;
}

.wk-explanation-box.visible {
  display: block;
}

.wk-explanation-title {
  font-size: 0.95rem;
  font-weight: 700;
  margin-bottom: 0.35rem;
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.wk-explanation-text {
  font-size: 0.95rem;
  color: var(--text-muted);
  line-height: 1.5;
}

/* ==============================================================================
   QUIZ SETUP SCREEN (Difficulty & Length Selector)
   ============================================================================== */
.wk-setup-card {
  text-align: center;
  padding: 2rem 1.5rem;
}

.wk-setup-header {
  margin-bottom: 1.5rem;
}

.wk-setup-title {
  font-size: 1.5rem;
  font-weight: 800;
  margin-bottom: 0.5rem;
}

.wk-setup-desc {
  color: var(--text-muted);
  font-size: 0.95rem;
}

.wk-setup-section {
  margin-bottom: 1.75rem;
  text-align: left;
}

.wk-setup-label {
  display: block;
  font-size: 0.9rem;
  font-weight: 700;
  color: var(--text);
  margin-bottom: 0.75rem;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.wk-pills-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 0.75rem;
}

.wk-length-pills-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 0.5rem;
}

@media (max-width: 480px) {
  .wk-length-pills-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

.wk-pill-btn {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 0.25rem;
  padding: 0.85rem 0.5rem;
  background-color: var(--surface-2);
  border: 2px solid var(--border);
  border-radius: var(--radius);
  color: var(--text);
  font-size: 0.95rem;
  font-weight: 700;
  cursor: pointer;
  transition: var(--transition);
  user-select: none;
}

.wk-pill-btn:hover {
  border-color: var(--primary);
  background-color: var(--primary-light);
  color: var(--primary);
}

.wk-pill-btn.active {
  border-color: var(--primary);
  background-color: var(--primary);
  color: #ffffff;
  box-shadow: var(--shadow-md);
}

.wk-pill-btn.active.pill-easy {
  background-color: var(--success);
  border-color: var(--success);
  color: #ffffff;
}

.wk-pill-btn.active.pill-medium {
  background-color: #f59e0b;
  border-color: #f59e0b;
  color: #ffffff;
}

.wk-pill-btn.active.pill-hard {
  background-color: var(--danger);
  border-color: var(--danger);
  color: #ffffff;
}

.wk-pill-btn:disabled,
.wk-pill-btn.disabled {
  opacity: 0.4;
  cursor: not-allowed !important;
  pointer-events: none;
  background-color: var(--surface-3);
  border-style: dashed;
}

.wk-setup-notice {
  font-size: 0.88rem;
  color: var(--text-muted);
  margin-bottom: 1.5rem;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  padding: 0.5rem 1rem;
  background-color: var(--surface-2);
  border-radius: var(--radius-sm);
  border: 1px solid var(--border);
}

.wk-setup-notice.warning {
  color: #d97706;
  border-color: rgba(217, 119, 6, 0.3);
  background-color: rgba(217, 119, 6, 0.08);
}

.wk-setup-placeholder {
  text-align: center;
  padding: 2.5rem 1.5rem;
  background-color: var(--surface);
  border: 2px dashed var(--border);
  border-radius: var(--radius-lg);
  margin-bottom: 2rem;
}

.wk-setup-placeholder-title {
  font-size: 1.25rem;
  font-weight: 800;
  margin-bottom: 0.5rem;
}

.wk-setup-placeholder-desc {
  font-size: 0.95rem;
  color: var(--text-muted);
  max-width: 480px;
  margin: 0 auto 1.25rem;
}
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
}

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(6px); }
  to { opacity: 1; transform: translateY(0); }
}

.wk-quiz-actions {
  display: flex;
  justify-content: flex-end;
  gap: 0.75rem;
}

/* ==============================================================================
   RESULTS SCREEN
   ============================================================================== */
.wk-results-card {
  text-align: center;
  padding: 2.5rem 1.5rem;
}

.wk-results-badge {
  font-size: 1.25rem;
  font-weight: 800;
  margin-bottom: 0.5rem;
}

.wk-score-circle {
  display: inline-flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  width: 140px;
  height: 140px;
  border-radius: var(--radius-full);
  background: linear-gradient(135deg, var(--primary), var(--secondary));
  color: #ffffff;
  margin: 1rem auto 1.5rem;
  box-shadow: var(--shadow-lg);
}

.wk-score-number {
  font-size: 2.5rem;
  font-weight: 900;
  line-height: 1;
}

.wk-score-percent {
  font-size: 0.9rem;
  font-weight: 600;
  opacity: 0.9;
}

.wk-results-msg {
  font-size: 1.1rem;
  color: var(--text-muted);
  max-width: 500px;
  margin: 0 auto 2rem;
}

.wk-results-buttons {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 0.75rem;
  margin-bottom: 2rem;
}

/* Social Share Block */
.wk-share-section {
  border-top: 1px solid var(--border);
  padding-top: 1.5rem;
  margin-top: 1.5rem;
}

.wk-share-title {
  font-size: 0.95rem;
  font-weight: 700;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: 1rem;
}

.wk-share-grid {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 0.5rem;
}

.wk-share-btn {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.5rem 1rem;
  border-radius: var(--radius-full);
  font-size: 0.85rem;
  font-weight: 600;
  color: #ffffff;
  text-decoration: none;
  transition: var(--transition);
}

.wk-share-btn:hover {
  text-decoration: none;
  color: #ffffff;
  transform: translateY(-1px);
}

.wk-share-whatsapp { background-color: #25d366; }
.wk-share-facebook { background-color: #1877f2; }
.wk-share-twitter { background-color: #000000; }
.wk-share-copy { background-color: var(--surface-3); color: var(--text); }
.wk-share-copy:hover { background-color: var(--border-focus); color: #ffffff; }

/* ==============================================================================
   CATEGORIES GRID & TRENDING
   ============================================================================== */
.wk-section-title {
  font-size: 1.5rem;
  font-weight: 800;
  margin-bottom: 1rem;
  display: flex;
  align-items: center;
  gap: 0.5rem;
  color: var(--text);
}

.wk-categories-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(140px, 1fr));
  gap: 0.75rem;
  margin-bottom: 2.5rem;
}

@media (min-width: 600px) {
  .wk-categories-grid {
    grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));
    gap: 1rem;
  }
}

.wk-category-card {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  padding: 1.25rem 1rem;
  background-color: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  text-decoration: none;
  color: var(--text);
  transition: var(--transition);
  position: relative;
  overflow: hidden;
}

.wk-category-card:hover {
  border-color: var(--primary);
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
  text-decoration: none;
}

.wk-category-icon {
  font-size: 1.75rem;
  margin-bottom: 0.5rem;
}

.wk-category-name {
  font-size: 1rem;
  font-weight: 700;
  line-height: 1.2;
}

.wk-category-count {
  font-size: 0.75rem;
  color: var(--text-muted);
  margin-top: 0.25rem;
}

/* ==============================================================================
   DAILY CHALLENGE BANNER
   ============================================================================== */
.wk-daily-banner {
  background: linear-gradient(135deg, #1e1b4b 0%, #312e81 100%);
  color: #ffffff;
  border-radius: var(--radius-lg);
  padding: 1.75rem;
  margin-bottom: 2rem;
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

@media (min-width: 600px) {
  .wk-daily-banner {
    flex-direction: row;
    align-items: center;
    justify-content: space-between;
  }
}

.wk-daily-title {
  font-size: 1.4rem;
  font-weight: 800;
}

.wk-daily-desc {
  font-size: 0.95rem;
  opacity: 0.9;
}

/* ==============================================================================
   AD SLOTS (AdSense Clean Layouts)
   ============================================================================== */
.wk-ad-slot {
  background-color: var(--surface-2);
  border: 1px dashed var(--border);
  border-radius: var(--radius);
  padding: 1rem;
  margin: 1.5rem 0;
  text-align: center;
  min-height: 100px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
}

.wk-ad-label {
  font-size: 0.65rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--text-muted);
  margin-bottom: 0.5rem;
}

/* ==============================================================================
   BLOGGER STANDARD POST & PAGE STYLES
   ============================================================================== */
.wk-post-article {
  background-color: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 1.5rem;
  margin-bottom: 2rem;
}

@media (min-width: 768px) {
  .wk-post-article {
    padding: 2.5rem;
  }
}

.wk-post-title {
  font-size: 1.75rem;
  font-weight: 800;
  line-height: 1.25;
  margin-bottom: 0.75rem;
}

.wk-post-meta {
  display: flex;
  gap: 1rem;
  font-size: 0.85rem;
  color: var(--text-muted);
  margin-bottom: 1.5rem;
  padding-bottom: 1rem;
  border-bottom: 1px solid var(--border);
}

.wk-post-body {
  font-size: 1.05rem;
  line-height: 1.7;
  color: var(--text);
}

.wk-post-body p {
  margin-bottom: 1.25rem;
}

.wk-post-body h2, .wk-post-body h3 {
  margin: 1.5rem 0 0.75rem;
  font-weight: 700;
}

.wk-post-body ul, .wk-post-body ol {
  margin: 1rem 0 1.25rem 1.5rem;
}

.wk-post-body blockquote {
  border-left: 4px solid var(--primary);
  padding-left: 1rem;
  font-style: italic;
  color: var(--text-muted);
  margin: 1.25rem 0;
}

/* ==============================================================================
   INSTANT SEARCH MODAL
   ============================================================================== */
.wk-modal-overlay {
  display: none;
  position: fixed;
  inset: 0;
  background-color: rgba(0, 0, 0, 0.6);
  backdrop-filter: blur(4px);
  z-index: 200;
  align-items: flex-start;
  justify-content: center;
  padding: 4rem 1rem 1rem;
}

.wk-modal-overlay.open {
  display: flex;
}

.wk-search-modal {
  width: 100%;
  max-width: 580px;
  background-color: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-lg);
  overflow: hidden;
  animation: modalSlide 0.2s ease;
}

@keyframes modalSlide {
  from { opacity: 0; transform: translateY(-15px); }
  to { opacity: 1; transform: translateY(0); }
}

.wk-search-input-wrap {
  display: flex;
  align-items: center;
  padding: 1rem 1.25rem;
  border-bottom: 1px solid var(--border);
  gap: 0.75rem;
}

.wk-search-input {
  width: 100%;
  border: none;
  background: transparent;
  font-size: 1.1rem;
  color: var(--text);
  outline: none;
}

.wk-search-results {
  max-height: 380px;
  overflow-y: auto;
  padding: 0.5rem;
}

.wk-search-item {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding: 0.75rem 1rem;
  border-radius: var(--radius);
  text-decoration: none;
  color: var(--text);
  transition: var(--transition);
}

.wk-search-item:hover {
  background-color: var(--surface-2);
  text-decoration: none;
  color: var(--primary);
}

/* ==============================================================================
   FOOTER
   ============================================================================== */
.wk-footer {
  margin-top: auto;
  background-color: var(--surface);
  border-top: 1px solid var(--border);
  padding: 3rem 0 2rem;
}

.wk-footer-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 2rem;
  margin-bottom: 2rem;
}

@media (min-width: 768px) {
  .wk-footer-grid {
    grid-template-columns: 2fr 1fr 1fr 1fr;
  }
}

.wk-footer-col h4 {
  font-size: 1rem;
  font-weight: 700;
  margin-bottom: 1rem;
  color: var(--text);
}

.wk-footer-links {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.wk-footer-link {
  font-size: 0.9rem;
  color: var(--text-muted);
  text-decoration: none;
}

.wk-footer-link:hover {
  color: var(--primary);
  text-decoration: underline;
}

.wk-footer-bottom {
  border-top: 1px solid var(--border);
  padding-top: 1.5rem;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  font-size: 0.85rem;
  color: var(--text-muted);
}

@media (min-width: 600px) {
  .wk-footer-bottom {
    flex-direction: row;
  }
}

.wk-social-row {
  display: flex;
  gap: 0.75rem;
}

.wk-social-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 36px;
  height: 36px;
  border-radius: var(--radius-full);
  background-color: var(--surface-2);
  color: var(--text);
  transition: var(--transition);
}

.wk-social-icon:hover {
  background-color: var(--primary);
  color: #ffffff;
}

