// Quiz Categories Registry categories: [ { id: "nursing", name: "Nursing", slug: "nursing", icon: "🩺", description: "Fundamental and clinical nursing knowledge, nursing process, and patient care.", color: "#0284c7" }, { id: "nclex", name: "NCLEX", slug: "nclex", icon: "📋", description: "NCLEX-RN & NCLEX-PN exam practice questions, triage, prioritization, and safety.", color: "#0369a1" }, { id: "medical", name: "Medical", slug: "medical", icon: "🏥", description: "General medical practice, clinical scenarios, diagnostics, and pathology.", color: "#0d9488" }, { id: "medical-terminology", name: "Medical Terminology", slug: "medical-terminology", icon: "📖", description: "Prefixes, suffixes, root words, and essential healthcare vocabulary.", color: "#059669" }, { id: "diseases", name: "Diseases & Disorders", slug: "diseases", icon: "🦠", description: "Infectious diseases, chronic illnesses, symptoms, and disease pathophysiology.", color: "#d97706" }, { id: "anatomy", name: "Anatomy & Physiology", slug: "anatomy", icon: "🫀", description: "Human body systems, organ functions, skeletal structure, and physiology.", color: "#e11d48" }, { id: "pharmacology", name: "Pharmacology", slug: "pharmacology", icon: "💊", description: "Drug classes, mechanisms of action, adverse effects, and dosage calculations.", color: "#7c3aed" }, { id: "entertainment", name: "Entertainment", slug: "entertainment", icon: "🎬", description: "Pop culture, cinema, blockbusters, and entertainment trivia.", color: "#db2777" }, { id: "movies", name: "Movies", slug: "movies", icon: "🍿", description: "Classic cinema, Oscar winners, movie quotes, and box office hits.", color: "#be185d" }, { id: "tv-shows", name: "TV Shows", slug: "tv-shows", icon: "📺", description: "Hit television series, streaming shows, sitcoms, and Emmy winners.", color: "#9333ea" }, { id: "drama", name: "Drama", slug: "drama", icon: "🎭", description: "Global drama series, plot twists, theatrical arts, and famous storylines.", color: "#c026d3" }, { id: "celebrity", name: "Celebrity", slug: "celebrity", icon: "⭐", description: "Famous personalities, iconic moments, biographies, and stars.", color: "#f59e0b" }, { id: "music", name: "Music", slug: "music", icon: "🎵", description: "Music genres, artists, legendary albums, instruments, and charts.", color: "#ec4899" }, { id: "general-knowledge", name: "General Knowledge", slug: "general-knowledge", icon: "🌍", description: "Trivia from around the world spanning culture, facts, and trivia.", color: "#4f46e5" }, { id: "history", name: "History", slug: "history", icon: "🏛️", description: "World history, ancient civilizations, world wars, and milestones.", color: "#b45309" }, { id: "geography", name: "Geography", slug: "geography", icon: "🗺️", description: "Capitals, world flags, mountain ranges, rivers, and country trivia.", color: "#047857" }, { id: "science", name: "Science", slug: "science", icon: "🔬", description: "Physics, chemistry, biology, astronomy, and scientific principles.", color: "#2563eb" }, { id: "engineering", name: "Engineering", slug: "engineering", icon: "⚙️", description: "Core engineering disciplines, design principles, and problem solving.", color: "#475569" }, { id: "electrical", name: "Electrical", slug: "electrical", icon: "⚡", description: "Ohm's law, circuit analysis, wiring standards, and electrical safety.", color: "#eab308" }, { id: "electrical-symbols", name: "Electrical Symbols", slug: "electrical-symbols", icon: "🔌", description: "Schematic symbols, blueprint reading, and circuit diagram symbols.", color: "#ca8a04" }, { id: "electronics", name: "Electronics", slug: "electronics", icon: "💡", description: "Semiconductors, transistors, microcontrollers, and logic gates.", color: "#0891b2" }, { id: "hvac", name: "HVAC", slug: "hvac", icon: "❄️", description: "Heating, ventilation, air conditioning, refrigeration, and psychrometrics.", color: "#06b6d4" }, { id: "technology", name: "Technology", slug: "technology", icon: "💻", description: "Innovations, internet history, AI, software, and tech gadgets.", color: "#3b82f6" }, { id: "computers", name: "Computers", slug: "computers", icon: "🖥️", description: "Computer hardware, operating systems, networking, and architecture.", color: "#6366f1" }, { id: "automotive", name: "Automotive", slug: "automotive", icon: "🚗", description: "Engine mechanics, vehicle diagnostics, automotive systems, and EV tech.", color: "#dc2626" }, { id: "iq-logic", name: "IQ & Logic", slug: "iq-logic", icon: "🧩", description: "Pattern recognition, logic puzzles, deductive reasoning, and brain teasers.", color: "#8b5cf6" }, { id: "mathematics", name: "Mathematics", slug: "mathematics", icon: "📐", description: "Algebra, geometry, arithmetic, probabilities, and calculus fundamentals.", color: "#10b981" }, { id: "english", name: "English & Grammar", slug: "english", icon: "✍️", description: "Grammar rules, vocabulary, idioms, reading comprehension, and syntax.", color: "#f97316" }, { id: "mixed-quiz", name: "Mixed Quiz", slug: "mixed-quiz", icon: "🎲", description: "A dynamic randomized blend of questions across all knowledge categories.", color: "#6b7280" } ] };
// CommonJS export for Node.js test runners & browser window exposure if (typeof module !== "undefined" && module.exports) { module.exports = { WKQUIZ_CONFIG }; } if (typeof window !== "undefined") { window.WKQUIZ_CONFIG = WKQUIZ_CONFIG; }
/* ========================================================================= */ /* 2. COMPILED QUESTION BANK */ /* ========================================================================= */ /** * WKQUIZ COMPILED QUESTION BANK * Auto-generated by scripts/build.js from question-bank/*.json * Total Questions: 2285 */
const WKQUIZ_QUESTIONS = [ { "id": "ANAT-000001", "category": "Anatomy & Physiology", "subcategory": "Cardiovascular", "difficulty": "easy", "question": "Which heart chamber pumps oxygenated blood into the aorta?", "options": [ "Left Ventricle", "Right Ventricle", "Left Atrium", "Right Atrium" ], "answer": 0, "explanation": "Left ventricle pumps into systemic circulation.", "tags": [ "anatomy & physiology" ], "status": "active" }, { "id": "ANAT-000002", "category": "Anatomy & Physiology", "subcategory": "Skeletal", "difficulty": "easy", "question": "What is the longest and strongest bone in the human body?", "options": [ "Femur", "Tibia", "Humerus", "Radius" ], "answer": 0, "explanation": "The femur is the longest human bone.", "tags": [ "anatomy & physiology" ], "status": "active" }, { "id": "ANAT-000003", "category": "Anatomy & Physiology", "subcategory": "Circulatory", "difficulty": "easy", "question": "Which blood vessels carry oxygen-depleted blood from the body back to the heart?", "options": [ "Veins", "Arteries", "Arterioles", "Capillaries" ], "answer": 0, "explanation": "Systemic veins return deoxygenated blood to the right atrium.", "tags": [ "anatomy & physiology" ], "status": "active" }, { "id": "ANAT-000004", "category": "Anatomy & Physiology", "subcategory": "Sensory", "difficulty": "easy", "question": "Which part of the human eye contains photoreceptor cells (rods and cones)?", "options": [ "Retina", "Cornea", "Lens", "Iris" ], "answer": 0, "explanation": "The retina converts light into neural signals via rods and cones.", "tags": [ "anatomy & physiology" ], "status": "active" }, { "id": "ANAT-000005", "category": "Anatomy & Physiology", "subcategory": "Neuroanatomy", "difficulty": "medium", "question": "Which brain structure coordinates voluntary muscle balance and equilibrium?", "options": [ "Cerebellum", "Cerebrum", "Hypothalamus", "Medulla" ], "answer": 0, "explanation": "Cerebellum coordinates balance.", "tags": [ "anatomy & physiology" ], "status": "active" }, { "id": "ANAT-000006", "category": "Anatomy & Physiology", "subcategory": "Respiratory", "difficulty": "medium", "question": "What dome-shaped muscle is the primary muscle of inspiration?", "options": [ "Diaphragm", "Internal intercostals", "Sternocleidomastoid", "Abdominals" ], "answer": 0, "explanation": "The diaphragm is the primary inspiratory muscle.", "tags": [ "anatomy & physiology" ], "status": "active" }, { "id": "ANAT-000007", "category": "Anatomy & Physiology", "subcategory": "Renal", "difficulty": "medium", "question": "What is the basic functional microscopic unit of the human kidney?", "options": [ "Nephron", "Alveolus", "Hepatocyte", "Neuron" ], "answer": 0, "explanation": "The nephron filters blood and forms urine.", "tags": [ "anatomy & physiology" ], "status": "active" }, { "id": "ANAT-000008", "category": "Anatomy & Physiology", "subcategory": "Digestive", "difficulty": "medium", "question": "Where in the human digestive tract does the vast majority of nutrient absorption take place?", "options": [ "Small Intestine (Duodenum/Jejunum/Ileum)", "Stomach", "Large Intestine", "Esophagus" ], "answer": 0, "explanation": "The small intestine's villi absorb nutrients into circulation.", "tags": [ "anatomy & physiology" ], "status": "active" }, { "id": "ANAT-000009", "category": "Anatomy & Physiology", "subcategory": "Endocrine", "difficulty": "hard", "question": "The islets of Langerhans are endocrine clusters situated within which organ?", "options": [ "Pancreas", "Liver", "Spleen", "Thyroid" ], "answer": 0, "explanation": "Islets of Langerhans reside in the pancreas.", "tags": [ "anatomy & physiology" ], "status": "active" }, { "id": "ANAT-000010", "category": "Anatomy & Physiology", "subcategory": "Cardiac Conduction", "difficulty": "hard", "question": "What is the intrinsic pacemaker of the human heart that initiates normal sinus rhythm?", "options": [ "Sinoatrial (SA) Node", "Atrioventricular (AV) Node", "Bundle of His", "Purkinje Fibers" ], "answer": 0, "explanation": "The SA node spontaneously depolarizes at 60-100 bpm.", "tags": [ "anatomy & physiology" ], "status": "active" }, { "id": "ANAT-000011", "category": "Anatomy & Physiology", "subcategory": "Neurophysiology", "difficulty": "hard", "question": "During the depolarization phase of an action potential in a neuron, which ion rushes rapidly into the cell?", "options": [ "Sodium (Na+) ions", "Potassium (K+) ions", "Chloride (Cl-) ions", "Calcium (Ca2+) ions" ], "answer": 0, "explanation": "Voltage-gated sodium channels open, causing rapid Na+ influx.", "tags": [ "anatomy & physiology" ], "status": "active" }, { "id": "ANAT-000012", "category": "Anatomy & Physiology", "subcategory": "Skeletal", "difficulty": "easy", "question": "How many total bones make up the adult human skeleton?", "options": [ "206 bones", "300 bones", "180 bones", "250 bones" ], "answer": 0, "explanation": "An adult human skeleton consists of 206 bones.", "tags": [ "anatomy & physiology" ], "status": "active" }, { "id": "ANAT-000013", "category": "Anatomy & Physiology", "subcategory": "Endocrine", "difficulty": "medium", "question": "Which endocrine gland is located at the base of the brain and often termed the 'Master Gland'?", "options": [ "Pituitary gland", "Thyroid gland", "Adrenal gland", "Pineal gland" ], "answer": 0, "explanation": "The pituitary gland regulates multiple hormone axes under hypothalamic control.", "tags": [ "anatomy & physiology" ], "status": "active" }, { "id": "ANAT-000014", "category": "Anatomy & Physiology", "subcategory": "Renal", "difficulty": "hard", "question": "Which segment of the nephron is the primary site of action for Loop Diuretics such as Furosemide?", "options": [ "Thick ascending limb of the Loop of Henle", "Proximal convoluted tubule", "Distal convoluted tubule", "Cortical collecting duct" ], "answer": 0, "explanation": "Loop diuretics inhibit the Na+/K+/2Cl- cotransporter in the thick ascending limb of Henle.", "tags": [ "anatomy & physiology" ], "status": "active" }, { "id": "ANAT-000015", "category": "Anatomy & Physiology", "subcategory": "Digestive", "difficulty": "easy", "question": "Which muscular tube connects the pharynx to the stomach?", "options": [ "Esophagus", "Trachea", "Duodenum", "Larynx" ], "answer": 0, "explanation": "The esophagus transports food boluses via peristalsis to the stomach.", "tags": [ "anatomy & physiology" ], "status": "active" }, { "id": "ANAT-000016", "category": "Anatomy & Physiology", "subcategory": "Nervous", "difficulty": "medium", "question": "Which cranial nerve (CN X) provides extensive parasympathetic innervation to the heart, lungs, and GI tract?", "options": [ "Vagus Nerve (CN X)", "Facial Nerve (CN VII)", "Trigeminal Nerve (CN V)", "Glossopharyngeal Nerve (CN IX)" ], "answer": 0, "explanation": "The Vagus nerve is the main parasympathetic nerve.", "tags": [ "anatomy & physiology" ], "status": "active" }, { "id": "ANAT-000017", "category": "Anatomy & Physiology", "subcategory": "Renal", "difficulty": "hard", "question": "What specialized cellular apparatus in the nephron senses sodium concentration and secretes Renin?", "options": [ "Juxtaglomerular Apparatus (JGA)", "Bowman's Capsule", "Podocytes", "Loop of Henle" ], "answer": 0, "explanation": "The JGA secretes renin in response to decreased renal perfusion or sodium delivery.", "tags": [ "anatomy & physiology" ], "status": "active" }, { "id": "ANATOMY-PHYSIOLOGY-EASY-001-1", "category": "Anatomy & Physiology", "subcategory": "Anatomy & Physiology", "difficulty": "easy", "question": "Which term is best described by the following definition: a muscular organ that pumps blood through the circulation?", "options": [ "Pituitary gland", "Large intestine", "Heart", "Cerebellum" ], "answer": 2, "explanation": "The correct answer is Heart. It matches the defining characteristic or role described in the question.", "tags": [ "anatomy" ], "status": "active" }, { "id": "ANATOMY-PHYSIOLOGY-MEDIUM-001-2", "