al-symbols" ], "status": "active" }, { "id": "ELEC-000001", "category": "Electrical", "subcategory": "Ohm's Law", "difficulty": "easy", "question": "According to Ohm's Law, what formula calculates voltage?", "options": [ "V = I × R", "V = I / R", "V = R / I", "V = I + R" ], "answer": 0, "explanation": "Voltage = Current (I) × Resistance (R).", "tags": [ "electrical" ], "status": "active" }, { "id": "ELEC-000002", "category": "Electrical", "subcategory": "Safety", "difficulty": "easy", "question": "What is the function of a Ground Fault Circuit Interrupter (GFCI)?", "options": [ "Protect people from shock by detecting ground current leakage", "Prevent circuit overloads", "Step down voltage", "Convert AC to DC" ], "answer": 0, "explanation": "GFCIs prevent electrocution from ground faults.", "tags": [ "electrical" ], "status": "active" }, { "id": "ELEC-000003", "category": "Electrical", "subcategory": "Conductors", "difficulty": "easy", "question": "Which metal is standard for residential electrical wiring?", "options": [ "Copper", "Gold", "Steel", "Lead" ], "answer": 0, "explanation": "Copper is the industry standard conductor.", "tags": [ "electrical" ], "status": "active" }, { "id": "ELEC-000004", "category": "Electrical", "subcategory": "Grid", "difficulty": "easy", "question": "What is the AC utility frequency in North America?", "options": [ "60 Hz", "50 Hz", "120 Hz", "400 Hz" ], "answer": 0, "explanation": "North American power grids operate at 60 Hz.", "tags": [ "electrical" ], "status": "active" }, { "id": "ELEC-000005", "category": "Electrical", "subcategory": "Circuits", "difficulty": "easy", "question": "In a series electrical circuit, what quantity remains identical through every component?", "options": [ "Current (Amperes)", "Voltage (Volts)", "Power (Watts)", "Resistance (Ohms)" ], "answer": 0, "explanation": "In a series circuit, current is uniform throughout.", "tags": [ "electrical" ], "status": "active" }, { "id": "ELEC-000006", "category": "Electrical", "subcategory": "Units", "difficulty": "easy", "question": "What unit measures electrical resistance?", "options": [ "Ohm (Ω)", "Ampere", "Volt", "Watt" ], "answer": 0, "explanation": "Resistance is measured in Ohms.", "tags": [ "electrical" ], "status": "active" }, { "id": "ELEC-000007", "category": "Electrical", "subcategory": "Power", "difficulty": "medium", "question": "If a 120V circuit draws 5A of current, what is the power consumed?", "options": [ "600 Watts", "24 Watts", "125 Watts", "60 Watts" ], "answer": 0, "explanation": "P = V × I = 120 × 5 = 600 Watts.", "tags": [ "electrical" ], "status": "active" }, { "id": "ELEC-000008", "category": "Electrical", "subcategory": "Wire Sizing", "difficulty": "medium", "question": "What copper wire gauge is standard for a 20A branch circuit?", "options": [ "12 AWG", "14 AWG", "10 AWG", "16 AWG" ], "answer": 0, "explanation": "12 AWG copper wire is rated for 20 Amps.", "tags": [ "electrical" ], "status": "active" }, { "id": "ELEC-000009", "category": "Electrical", "subcategory": "Transformers", "difficulty": "medium", "question": "A transformer with a 10:1 turns ratio converts 240V primary into what secondary voltage?", "options": [ "24V AC", "2400V AC", "12V AC", "120V AC" ], "answer": 0, "explanation": "240V / 10 = 24V AC secondary output.", "tags": [ "electrical" ], "status": "active" }, { "id": "ELEC-000010", "category": "Electrical", "subcategory": "Resistance", "difficulty": "medium", "question": "What is the equivalent resistance of two 10-Ohm resistors wired in parallel?", "options": [ "5 Ohms", "20 Ohms", "10 Ohms", "2.5 Ohms" ], "answer": 0, "explanation": "R_parallel = (10 × 10) / (10 + 10) = 5 Ohms.", "tags": [ "electrical" ], "status": "active" }, { "id": "ELEC-000011", "category": "Electrical", "subcategory": "Energy", "difficulty": "medium", "question": "Electric utility companies bill residential electrical energy consumption in what unit?", "options": [ "Kilowatt-hours (kWh)", "Kilowatts (kW)", "Ampere-hours (Ah)", "Megajoules" ], "answer": 0, "explanation": "Electrical energy is billed in kilowatt-hours (kWh).", "tags": [ "electrical" ], "status": "active" }, { "id": "ELEC-000012", "category": "Electrical", "subcategory": "AC Theory", "difficulty": "hard", "question": "In a purely inductive AC circuit, what is the phase relationship between voltage and current?", "options": [ "Voltage leads current by 90 degrees", "Current leads voltage by 90 degrees", "They are in phase", "Voltage leads current by 180 degrees" ], "answer": 0, "explanation": "In an inductor, voltage leads current by 90° (ELI).", "tags": [ "electrical" ], "status": "active" }, { "id": "ELEC-000013", "category": "Electrical", "subcategory": "Three-Phase", "difficulty": "hard", "question": "In a 3-phase Wye system, what is the formula for line-to-line voltage from line-to-neutral voltage?", "options": [ "V_LL = √3 × V_LN", "V_LL = V_LN / √3", "V_LL = 3 × V_LN", "V_LL = V_LN" ], "answer": 0, "explanation": "Line-to-line voltage equals line-to-neutral multiplied by √3 (1.732).", "tags": [ "electrical" ], "status": "active" }, { "id": "ELEC-000014", "category": "Electrical", "subcategory": "Power Factor", "difficulty": "hard", "question": "What does a lagging power factor in an industrial AC plant indicate?", "options": [ "The load is predominantly inductive (motors/transformers)", "The load is purely capacitive", "Voltage and current are in phase", "Power consumption is zero" ], "answer": 0, "explanation": "Inductive loads draw lagging current, lowering power factor.", "tags": [ "electrical" ], "status": "active" }, { "id": "ELEC-000015", "category": "Electrical", "subcategory": "Capacitive Reactance", "difficulty": "hard", "question": "What happens to the capacitive reactance (X_C) of a capacitor as the AC frequency increases?", "options": [ "It decreases inversely with frequency", "It increases proportionally", "It remains constant", "It drops to zero instantly" ], "answer": 0, "explanation": "X_C = 1 / (2πfC), so reactance decreases as frequency increases.", "tags": [ "electrical" ], "status": "active" }, { "id": "ELEC-000016", "category": "Electrical", "subcategory": "Safety", "difficulty": "easy", "question": "What standard color insulation denotes the equipment grounding conductor in US branch circuits?", "options": [ "Green or Bare Copper", "Black", "White", "Red" ], "answer": 0, "explanation": "Ground wires are green or bare copper; white/gray is neutral; black/red are hot.", "tags": [ "electrical" ], "status": "active" }, { "id": "ELEC-000017", "category": "Electrical", "subcategory": "Motors", "difficulty": "medium", "question": "What device is connected in series with the start winding of a single-phase AC induction motor to create phase shift?", "options": [ "Start Capacitor", "Step-up transformer", "Bridge rectifier", "Zener diode" ], "answer": 0, "explanation": "Start capacitors create a phase angle shift between start and run windings to generate starting torque.", "tags": [ "electrical" ], "status": "active" }, { "id": "ELEC-000018", "category": "Electrical", "subcategory": "Calculations", "difficulty": "hard", "question": "What is the total power (P) in a balanced 3-phase circuit with line voltage V_L, line current I_L, and power factor PF?", "options": [ "P = √3 × V_L × I_L × PF", "P = 3 × V_L × I_L × PF", "P = V_L × I_L × PF", "P = V_L / (I_L × PF)" ], "answer": 0, "explanation": "Three-phase power: P = √3 · V_L · I_L · PF.", "tags": [ "electrical" ], "status": "active" }, { "id": "ELEC-000019", "category": "Electrical", "subcategory": "Instruments", "difficulty": "easy", "question": "What handheld electrical test instrument measures voltage, current, and resistance in a single unit?", "options": [ "Multimeter (DMM)", "Oscilloscope", "Wattmeter", "Galvanometer" ], "answer": 0, "explanation": "Digital multimeters combine voltmeter, ammeter, and ohmmeter functions.", "tags": [ "electrical" ], "status": "active" }, { "id": "ELEC-000020", "category": "Electrical", "subcategory": "Conduit", "difficulty": "medium", "question": "What does 'EMT' stand for in electrical wiring conduits?", "options": [ "Electrical Metallic Tubing", "Electromagnetic Transfer", "Emergency Main Transmission", "Earth Metal Terminal" ], "answer": 0, "explanation": "EMT is thin-wall steel electrical metallic tubing.", "tags": [ "electrical" ], "status": "active" }, { "id": "ELEC-000021", "category": "Electrical", "subcategory": "Harmonics", "difficulty": "hard", "question": "In non-linear electrical loads (e.g. computer power supplies), which harmonic causes heavy current on the neutral conductor?", "options": [ "Triplen Harmonics (3rd, 9th, 15th harmonics)", "2nd Harmonic", "4th Harmonic", "6th Harmonic" ], "answer": 0, "explanation": "Triplen harmonics add arithmetically in the neutral conductor of 3-phase systems.", "tags": [ "electrical" ], "status": "active" }, { "id": "ELECTRICAL-EASY-001-1", "category": "Electrical", "subcategory": "Electrical", "difficulty": "easy", "question": "Which term is best described by the following definition: electric potential difference between two points?", "options": [ "Multimeter", "Voltage", "Open circuit", "Circuit load" ], "answer": 1, "explanation": "The correct answer is Voltage. It matches the defining characteristic or role described in the question.", "tags": [ "electrical" ], "status": "active" }, { "id": "ELECTRICAL-MEDIUM-001-2", "category": "Electrical", "subcategory": "Electrical", "difficulty": "medium", "question": "Which statement best describes Voltage?", "options": [ "a circuit in which branches share the same two nodes", "electric potential difference between two points", "a test instrument that can measure electrical quantities such as voltage, current, and resistance", "an overcurrent protection device that opens when its element melts" ], "answer": 1, "explanation": "The correct answer is electric potential difference between two points. It matches the defining characteristic or role described in the question.", "tags": [ "electrical" ], "status": "active" }, { "id": "ELECTRICAL-HARD-001-3", "category": "Electrical", "subcategory": "Electrical", "difficulty": "hard", "question": "A learner encounters this situation: a multimeter measures the potential difference across a component. Which concept best matches it?", "options": [ "Current", "Voltage", "Alternating current", "Ground" ], "answer": 1, "explanation": "The correct answer is Voltage. It matches the defining characteristic or role described in the question.", "tags": [ "electrical" ], "status": "active" }, { "id": "ELECTRICAL-EASY-001-4", "category": "Electrical", "subcategory": "Electrical", "difficulty": "easy", "question": "Which option best identifies the primary purpose or role associated with Voltage?", "options": [ "verify an unbroken path", "cause fault current and protective-device operation", "provide the electrical potential that drives current", "stop current flow" ], "answer": 2, "explanation": "The correct answer is provide the electrical potential that drives current. It matches the defining characteristic or role described in the question.", "tags": [ "electrical" ], "status": "active" }, { "id": "ELECTRICAL-EASY-002-1", "category": "Electrical", "subcategory": "Electrical", "difficulty": "easy", "question": "Which term is best described by the following definition: the rate of flow of electric charge?", "options": [ "Open circuit", "Current", "Multimeter", "Relay" ], "answer": 1, "explanation": "The correct answer is Current. It matches the defining characteristic or role described in the question.", "tags": [ "electrical" ], "status": "active" }, { "id": "ELECTRICAL-MEDIUM-002-2", "category": "Electrical", "subcategory": "Electrical", "difficulty": "medium", "question": "Which statement best describes Current?", "options": [ "the relationship V = IR for an ohmic element under specified conditions", "the rate of flow of electric charge", "opposition to electric current", "electric current that flows with a constant polarity in the idealized basic sense" ], "answer": 1, "explanation": "The correct answer is the rate of flow of electric charge. It matches the defining characteristic or role described in the question.", "tags": [ "electrical" ], "status": "active" }, { "id": "ELECTRICAL-HARD-002-3", "category": "Electrical", "subcategory": "Electrical", "difficulty": "hard", "question": "A learner encounters this situation: amperes are used to measure it in a circuit. Which concept best matches it?", "options": [ "Current", "Inductor", "Contactor", "Circuit load" ], "answer": 0, "explanation": "The correct answer is Current. It matches the defining characteristic or role described in the question.", "tags": [ "electrical" ], "status": "active" }, { "id": "ELECTRICAL-MEDIUM-002-4", "category": "Electrical", "subcategory": "Electrical", "difficulty": "medium", "question": "Which option best identifies the primary purpose or role associated with Current?", "options": [ "switch higher-power loads", "protect and route conductors", "describe charge flow", "diagnose electrical circuits" ], "answer": 2, "explanation": "The correct answer is describe charge flow. It matches the defining characteristic or role described in the question.", "tags": [ "electrical" ], "status": "active" }, { "id": "ELECTRICAL-EASY-003-1", "category": "Electrical", "subcategory": "Electrical", "difficulty": "easy", "question": "Which term is best described by the following definition: opposition to electric current?", "options": [ "Resistance", "Relay", "Voltage", "Ground" ], "answer": 0, "explanation": "The correct answer is Resistance. It matches the defining characteristic or role described in the question.", "tags": [ "electrical" ], "status": "active" }, { "id": "ELECTRICAL-MEDIUM-003-2", "category": "Electrical", "subcategory": "Electrical", "difficulty": "medium", "question": "Which statement best describes Resistance?", "options": [ "an unintended low-impedance path that can produce excessive current", "a test instrument that can measure electrical quantities such as voltage, current, and resistance", "a raceway used to protect and route electrical conductors", "opposition to electric current" ], "answer": 3, "explanation": "The correct answer is opposition to electric current. It matches the defining characteristic or role described in the question.", "tags": [ "electrical" ], "status": "active" }, { "id": "ELECTRICAL-HARD-003-3", "category": "Electrical", "subcategory": "Electrical", "difficulty": "hard", "question": "A learner encounters this situation: a resistor limits current in a circuit. Which concept best matches it?", "options": [ "Open circuit", "Ground", "Transformer", "Resistance" ], "answer": 3, "explanation": "The correct answer is Resistance. It matches the defining characteristic or role described in the question.", "tags": [ "electrical" ], "status": "active" }, { "id": "ELECTRICAL-HARD-003-4", "category": "Electrical", "subcategory": "Electrical", "difficulty": "hard", "question": "Which option best identifies the primary purpose or role associated with Resistance?", "options": [ "oppose current flow", "store magnetic energy and oppose current change", "describe charge flow", "provide the electrical potential that drives current" ], "answer": 0, "explanation": "The correct answer is oppose current flow. It matches the defining characteristic or role described in the question.", "tags": [ "electrical" ], "status": "active" }, { "id": "ELECTRICAL-EASY-004-1", "category": "Electrical", "subcategory": "Electrical", "difficulty": "easy", "question": "Which term is best described by the following definition: the relationship V = IR for an ohmic element under specified conditions?", "options": [ "Current", "Diode", "Fuse", "Ohm's law" ], "answer": 3, "explanation": "The correct answer is Ohm's law. It matches the defining characteristic or role described in the question.", "tags": [ "electrical" ], "status": "active" }, { "id": "ELECTRICAL-MEDIUM-004-2", "category": "Electrical", "subcategory": "Electrical", "difficulty": "medium", "question": "Which statement best describes Ohm's law?", "options": [ "the relationship V = IR for an ohmic element under specified conditions", "a component that stores energy in a magnetic field", "the number of cycles or repetitions per second", "a reference point and/or conductive path used for electrical safety and circuit reference" ], "answer": 0, "explanation": "The correct answer is the relationship V = IR for an ohmic element under specified conditions. It matches the defining characteristic or role described in the question.", "tags": [ "electrical" ], "status": "active" }, { "id": "ELECTRICAL-HARD-004-3", "category": "Electrical", "subcategory": "Electrical", "difficulty": "hard", "question": "A learner encounters this situation: voltage, current, and resistance are related by a basic circuit equation. Which concept best matches it?", "options": [ "Current", "Ohm's law", "Diode", "Fuse" ], "answer": 1, "explanation": "The correct answer is Ohm's law. It matches the defining characteristic or role described in the question.", "tags": [ "electrical" ], "status": "active" }, { "id": "ELECTRICAL-EASY-004-4", "category": "Electrical", "subcategory": "Electrical", "difficulty": "easy", "question": "Which option best identifies the primary purpose or role associated with Ohm's law?", "options": [ "use electrical energy", "protect against overcurrent", "provide one current path", "analyze simple electrical circuits" ], "answer": 3, "explanation": "The correct answer is analyze simple electrical circuits. It matches the defining characteristic or role described in the question.", "tags": [ "electrical" ], "status": "active" }, { "id": "ELECTRICAL-EASY-005-1", "category": "Electrical", "subcategory": "Electrical", "difficulty": "easy", "question": "Which term is best described by the following definition: the rate of electrical energy transfer, commonly P = VI?", "options": [ "Open circuit", "Power", "Frequency", "Contactor" ], "answer": 1, "explanation": "The correct answer is Power. It matches the defining characteristic or role described in the question.", "tags": [ "electrical" ], "status": "active" }, { "id": "ELECTRICAL-HARD-005-3", "category": "Electrical", "subcategory": "Electrical", "difficulty": "hard", "question": "A learner encounters this situation: a load consumes electrical power measured in watts. Which concept best matches it?", "options": [ "Ohm's law", "Series circuit", "Power", "Transformer" ], "answer": 2, "explanation": "The correct answer is Power. It matches the defining characteristic or role described in the question.", "tags": [ "electrical" ], "status": "active" }, { "id": "ELECTRICAL-EASY-006-1", "category": "Electrical", "subcategory": "Electrical", "difficulty": "easy", "question": "Which term is best described by the following definition: a circuit in which components share a single current path?", "options": [ "Alternating current", "Contactor", "Ohm's law", "Series circuit" ], "answer": 3, "explanation": "The correct answer is Series circuit. It matches the defining characteristic or role described in the question.", "tags": [ "electrical" ], "status": "active" }, { "id": "ELECTRICAL-MEDIUM-006-2", "category": "Electrical", "subcategory": "Electrical", "difficulty": "medium", "question": "Which statement best describes Series circuit?", "options": [ "an overcurrent protection device that opens when its element melts", "the rate of flow of electric charge", "a circuit in which components share a single current path", "an electrically controlled switch commonly used for switching power circuits" ], "answer": 2, "explanation": "The correct answer is a circuit in which components share a single current path. It matches the defining characteristic or role described in the question.", "tags": [ "electrical" ], "status": "active" }, { "id": "ELECTRICAL-HARD-