ty": "medium", "question": "What is the antonym of 'Ephemeral'?", "options": [ "Permanent", "Fleeting", "Transient", "Short-lived" ], "answer": 0, "explanation": "Permanent is the opposite of ephemeral.", "tags": [ "english & grammar" ], "status": "active" }, { "id": "ENGL-000005", "category": "English & Grammar", "subcategory": "Rhetoric", "difficulty": "hard", "question": "What rhetorical figure uses understatement by denying the contrary (e.g. 'not bad')?", "options": [ "Litotes", "Chiasmus", "Synecdoche", "Metonymy" ], "answer": 0, "explanation": "Litotes expresses an affirmative by negating its opposite.", "tags": [ "english & grammar" ], "status": "active" }, { "id": "ENGL-000006", "category": "English & Grammar", "subcategory": "Syntax", "difficulty": "hard", "question": "What is the term for a clause that cannot stand alone as a complete sentence and starts with a subordinating conjunction?", "options": [ "Subordinate (Dependent) Clause", "Independent Clause", "Absolute Phrase", "Appositive" ], "answer": 0, "explanation": "A dependent clause cannot stand alone as a complete thought.", "tags": [ "english & grammar" ], "status": "active" }, { "id": "ENGL-000007", "category": "English & Grammar", "subcategory": "Punctuation", "difficulty": "easy", "question": "Which punctuation mark is used to show possession (e.g. 'Sarah's book') or contraction ('don't')?", "options": [ "Apostrophe (')", "Hyphen (-)", "Colon (:)", "Semicolon (;)" ], "answer": 0, "explanation": "Apostrophes denote possession and contractions.", "tags": [ "english & grammar" ], "status": "active" }, { "id": "ENGL-000008", "category": "English & Grammar", "subcategory": "Vocabulary", "difficulty": "medium", "question": "What word describes an exaggeration used for rhetorical emphasis, such as 'I have a million things to do'?", "options": [ "Hyperbole", "Metaphor", "Simile", "Oxymoron" ], "answer": 0, "explanation": "Hyperbole is intentional rhetorical exaggeration.", "tags": [ "english & grammar"